cd /tmp && node -e "
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } = require('docx');
const fs = require('fs');
const content = fs.readFileSync('/home/claude/jade_memory_full.md', 'utf8');
const lines = content.split('\n');
const children = [];

for (const line of lines) {
  if (line.startsWith('# ') && !line.startsWith('## ')) {
    children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: line.replace(/^# /, ''), bold: true, size: 32, font: 'Arial' })] }));
  } else if (line.startsWith('## ')) {
    children.push(new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: line.replace(/^## /, ''), bold: true, size: 28, font: 'Arial' })] }));
  } else if (line.startsWith('### ')) {
    children.push(new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun({ text: line.replace(/^### /, ''), bold: true, size: 24, font: 'Arial' })] }));
  } else if (line.startsWith('- ')) {
    children.push(new Paragraph({ children: [new TextRun({ text: '• ' + line.replace(/^- /, ''), size: 22, font: 'Arial' })] }));
  } else if (line.trim() === '---') {
    children.push(new Paragraph({ children: [new TextRun({ text: '', size: 22 })] }));
  } else if (line.trim() === '') {
    children.push(new Paragraph({ children: [new TextRun('')] }));
  } else {
    const bold = line.startsWith('**') && line.endsWith('**');
    const text = bold ? line.replace(/^\*\*/, '').replace(/\*\*$/, '') : line;
    children.push(new Paragraph({ children: [new TextRun({ text, size: 22, font: 'Arial', bold })] }));
  }
}

const doc = new Document({
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/jade_memory_full.docx', buf);
  console.log('Done');
});
"

