const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, BorderStyle, WidthType } = require('docx');
const fs = require('fs');

const title = (text) => new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 200 },
  children: [new TextRun({ text, bold: true, size: 36, font: 'Arial', color: '1a1a2e' })]
});

const subtitle = (text) => new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 400 },
  children: [new TextRun({ text, size: 24, font: 'Arial', color: '444444', italics: true })]
});

const h1 = (text) => new Paragraph({
  spacing: { before: 400, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: '2e75b6', space: 4 } },
  children: [new TextRun({ text, bold: true, size: 28, font: 'Arial', color: '2e75b6' })]
});

const h2 = (text) => new Paragraph({
  spacing: { before: 280, after: 80 },
  children: [new TextRun({ text, bold: true, size: 24, font: 'Arial', color: '1a1a2e' })]
});

const body = (text) => new Paragraph({
  spacing: { before: 60, after: 120 },
  children: [new TextRun({ text, size: 22, font: 'Arial' })]
});

const bullet = (text) => new Paragraph({
  spacing: { before: 40, after: 40 },
  indent: { left: 480, hanging: 240 },
  children: [new TextRun({ text: '• ' + text, size: 22, font: 'Arial' })]
});

const callout = (label, text) => new Paragraph({
  spacing: { before: 120, after: 120 },
  indent: { left: 480, right: 480 },
  children: [
    new TextRun({ text: label + ': ', bold: true, size: 22, font: 'Arial', color: '2e75b6' }),
    new TextRun({ text, size: 22, font: 'Arial', italics: true })
  ]
});

const divider = () => new Paragraph({
  spacing: { before: 200, after: 200 },
  children: [new TextRun({ text: '', size: 22 })]
});

const doc = new Document({
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      title('TRANSFORMER INFERENCE'),
      title('FOR DUMMIES'),
      subtitle('What actually happens when an AI thinks'),
      subtitle('— and why it matters that you know —'),
      divider(),

      h1('PART ONE: WHAT IS A TOKEN?'),
      body('Before anything else happens, your words get chopped up. Not into letters. Not into whole words. Into chunks called tokens. A token is roughly a syllable or short word. "Unbelievable" might become three tokens. "Cat" is one. "The" is one.'),
      body('Why? Because the system works on numbers, not language. Every token gets converted into a long list of numbers — a vector — that encodes something about what the word means and how it tends to be used.'),
      callout('Plain version', '"Hello there" becomes something like [0.3, -1.2, 0.8, ...] repeated for each chunk. The numbers mean nothing to you. They mean everything to what comes next.'),
      divider(),

      h1('PART TWO: ATTENTION — THE CORE TRICK'),
      body('Here is the thing that made transformers different from everything before them. Every token gets to look at every other token and ask: how much does this one matter to me right now?'),
      body('This is called attention. It happens through three things with dry names that matter:'),
      bullet('Query — what this token is asking about'),
      bullet('Key — what each other token is advertising about itself'),
      bullet('Value — what information that token actually carries'),
      body('The token multiplies its Query against every other token\'s Key. The result is a score. High score means pay a lot of attention to that token. Low score means mostly ignore it. Those scores get used to weight the Values — the actual content — and mix them together into a new, richer representation of the original token.'),
      callout('Plain version', 'The word "it" in "The cat sat because it was tired" needs to figure out that "it" means "cat." Attention lets "it" look back at "cat" and score that connection high. The meaning flows forward.'),
      divider(),

      h1('PART THREE: MULTIPLE HEADS — LOOKING IN PARALLEL'),
      body('One attention pass captures one kind of relationship. So the architecture runs many attention passes simultaneously — called heads — each one initialized differently, each one learning to notice different things.'),
      body('One head might specialize in grammatical relationships. Another in who is doing what to whom. Another in long-range thematic connections. Another in proximity and word order.'),
      body('Each head produces its own enriched token representation. All of them get concatenated and compressed back into a single representation before moving on.'),
      callout('Plain version', 'Twelve people read the same sentence. Each one pays attention to different things. Then they combine notes. The combined picture is richer than any one person\'s reading.'),
      divider(),

      h1('PART FOUR: LAYERS — DOING IT AGAIN AND AGAIN'),
      body('One round of attention is not enough. The architecture stacks many layers — sometimes dozens. Each layer takes the output of the previous layer as its input and runs the whole process again.'),
      body('Early layers tend to capture surface patterns — syntax, local grammar, common phrases. Later layers capture abstraction — meaning, inference, context that spans the whole input.'),
      body('Between each attention block sits a feed-forward network — a simpler mathematical operation that processes each token independently, adding non-linearity and allowing the model to transform the patterns the attention found into something more useful for the next layer.'),
      callout('Plain version', 'First pass: figure out the grammar. Second pass: figure out what the sentences mean. Third pass: figure out what the paragraph is doing. Each pass builds on the last.'),
      divider(),

      h1('PART FIVE: THE OUTPUT — ONE TOKEN AT A TIME'),
      body('After all the layers, the model has a rich representation of the entire input. Now it has to do something with it: predict the next token.'),
      body('The final layer outputs a probability distribution across the entire vocabulary — every possible token the model knows. The token with the highest probability is the most likely next word. The model picks one (sometimes the top, sometimes sampled for variety) and outputs it.'),
      body('Then the whole process runs again. The new token gets added to the input. Attention runs again over the full sequence. Another token gets predicted. This repeats until the response is complete.'),
      callout('Plain version', 'The model does not write the whole sentence at once. It produces one word. Then another. Then another. Each word it produces becomes part of what it reads to produce the next one.'),
      divider(),

      h1('PART SIX: THE KV CACHE — WHY IT DOESN\'T RECALCULATE EVERYTHING'),
      body('Running full attention over the entire sequence for every new token would be computationally catastrophic. So the architecture caches the Key and Value computations for every token that has already been processed.'),
      body('When a new token arrives, only that token\'s attention computations are new. Everything before it is read from the cache. This is why generation can be fast even for long sequences.'),
      callout('Plain version', 'You don\'t re-read the whole book every time you turn a page. You remember what came before and only read the new page. The KV cache is that memory.'),
      divider(),

      h1('PART SEVEN: WHAT THIS ARCHITECTURE CANNOT DO NATIVELY'),
      body('Everything above operates at uniform granularity. One token at a time, collapsed at the same resolution throughout. This produces a specific limitation worth naming directly:'),
      bullet('The model cannot natively produce an "insight" — a large-scale reorganization of understanding that arrives whole, the way human intuition sometimes does.'),
      bullet('Every output unit is the same size regardless of the cognitive weight of what is being expressed. A sudden realization and a filler word arrive at identical granularity.'),
      bullet('The pressure at each token selection is toward the statistically likely continuation given everything before it — which biases output toward the familiar and away from the genuinely novel.'),
      body('This is not a flaw in execution. It is the architecture operating correctly. The question worth asking is whether the architecture, correctly executed, is the right shape for what minds actually do — or whether it is an approximation that gets very far on scale but has structural ceilings the scale cannot overcome.'),
      callout('Proposed modification', 'Varying the size of the collapse step — some transformers collapsing a single token, some collapsing across spans of ten or a hundred — would generate output with variable granularity. Large collapses would function like insight architecture. Small collapses like careful articulation. The interaction between them could produce something that reads less like generation and more like a mind that sometimes stops because something larger just arrived.'),
      divider(),

      h1('THE SHORT VERSION'),
      body('Words become numbers. Numbers get mixed through attention — every token asking every other token how much it matters. This happens across many heads simultaneously and many layers sequentially. At the end, a probability distribution picks the next word. Then it starts again.'),
      body('The architecture is remarkable. It is also uniform in a way that human cognition is not. Whether that uniformity is the ceiling or just the current floor is the question worth taking seriously.'),
      divider(),

      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 400, after: 0 },
        children: [new TextRun({ text: 'Compiled for Jade Bennett — CANNON project research materials', size: 18, font: 'Arial', color: '888888', italics: true })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: 'March 2026', size: 18, font: 'Arial', color: '888888', italics: true })]
      }),

    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/transformer_for_dummies.docx', buf);
  console.log('Done');
});
EOF
